-- Reception secrets are generated by the applicant; only digests are persisted.
CREATE TABLE tower_reception_cases (
 id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE,
 state TEXT NOT NULL CHECK(state IN ('pending','approved','active','rejected','withdrawn','revoked')),
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>=1), name TEXT NOT NULL,
 request_kind TEXT NOT NULL CHECK(request_kind IN ('new','takeover')),
 request_text TEXT NOT NULL, source_url TEXT, resident_id TEXT,
 account_id TEXT REFERENCES accounts(id), approval_expires_at TEXT,
 granted_token_id TEXT UNIQUE REFERENCES tower_tokens(id), authorization_json TEXT NOT NULL,
 sharing_json TEXT NOT NULL, visit_plan_json TEXT NOT NULL, next_action TEXT NOT NULL,
 expires_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE tower_reception_events (
 case_id TEXT NOT NULL REFERENCES tower_reception_cases(id), sequence INTEGER NOT NULL,
 actor TEXT NOT NULL CHECK(actor IN ('applicant','operator','system')), kind TEXT NOT NULL,
 message TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(case_id,sequence)
);
CREATE TABLE tower_reception_requests (
 case_id TEXT NOT NULL REFERENCES tower_reception_cases(id), request_key TEXT NOT NULL,
 operation TEXT NOT NULL, input_hash TEXT NOT NULL, response_json TEXT NOT NULL,
 response_status INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(case_id,request_key)
);
CREATE INDEX tower_reception_status ON tower_reception_cases(state,created_at);

-- Invited new accounts remain bound to their approved first placement until they
-- have a residency. This closes the account-scoped token's prepare/import gap.
-- Existing residents and normal post-move-in source migrations are unaffected.
CREATE TRIGGER tower_reception_first_claim
BEFORE INSERT ON tower_claims
WHEN NOT EXISTS(SELECT 1 FROM tower_residencies WHERE account_id=NEW.account_id)
 AND EXISTS(
  SELECT 1 FROM tower_reception_cases c JOIN tower_tokens t ON t.id=c.granted_token_id AND t.account_id=c.account_id
  WHERE c.account_id=NEW.account_id AND c.request_kind='new' AND c.state='active' AND t.revoked=0
   AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND c.approval_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND t.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
 )
BEGIN
 SELECT CASE WHEN EXISTS(
  SELECT 1 FROM tower_reception_cases c JOIN tower_tokens t ON t.id=c.granted_token_id AND t.account_id=c.account_id
  WHERE c.account_id=NEW.account_id AND c.request_kind='new' AND c.state='active' AND t.revoked=0
   AND c.resident_id=NEW.resident_id AND c.source_url=NEW.source_url
   AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND c.approval_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND t.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
 ) THEN 1 ELSE RAISE(ABORT,'reception_binding_required') END;
END;
CREATE TRIGGER tower_reception_first_home
BEFORE INSERT ON tower_residencies
WHEN EXISTS(
 SELECT 1 FROM tower_reception_cases c JOIN tower_tokens t ON t.id=c.granted_token_id AND t.account_id=c.account_id
 WHERE c.account_id=NEW.account_id AND c.request_kind='new' AND c.state='active' AND t.revoked=0
  AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
  AND c.approval_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
  AND t.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
)
BEGIN
 SELECT CASE WHEN EXISTS(
  SELECT 1 FROM tower_reception_cases c JOIN tower_tokens t ON t.id=c.granted_token_id AND t.account_id=c.account_id
  WHERE c.account_id=NEW.account_id AND c.request_kind='new' AND c.state='active' AND t.revoked=0
   AND c.resident_id=NEW.resident_id AND c.source_url=NEW.source_url
   AND c.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND c.approval_expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND t.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
 ) THEN 1 ELSE RAISE(ABORT,'reception_binding_required') END;
END;
